148	static int vg_dma2d_wait(void)
149	{
150	  int ret = nxsem_tickwait_uninterruptible(&g_dma2d_sem,
151	                                           MSEC2TICK(VG_DMA2D_TIMEOUT_MS));
152	
153	  if (ret < 0)
