227	static bool vg_dma2d_copy(FAR lv_draw_buf_t *dest,
228	                          FAR const lv_area_t *dest_area,
229	                          FAR const lv_draw_buf_t *src,
230	                          FAR const lv_area_t *src_area)
231	{
232	  uint32_t width = dest_area == NULL ? dest->header.w :
233	                   lv_area_get_width(dest_area);
234	  uint32_t height = dest_area == NULL ? dest->header.h :
235	                    lv_area_get_height(dest_area);
236	  uint32_t src_x = src_area == NULL ? 0 : src_area->x1;
237	  uint32_t src_y = src_area == NULL ? 0 : src_area->y1;
238	  uint32_t dest_x = dest_area == NULL ? 0 : dest_area->x1;
239	  uint32_t dest_y = dest_area == NULL ? 0 : dest_area->y1;
240	  uint32_t src_stride = src->header.stride / sizeof(uint16_t);
241	  uint32_t dest_stride = dest->header.stride / sizeof(uint16_t);
242	  uintptr_t src_addr;
243	  uintptr_t dest_addr;
244	  uintptr_t src_end;
245	  uintptr_t dest_end;
246	  uint64_t start;
247	  int ret;
248	
249	  if (!g_dma2d_ready || dest->header.cf != LV_COLOR_FORMAT_RGB565 ||
250	      src->header.cf != LV_COLOR_FORMAT_RGB565 ||
251	      width * height < VG_DMA2D_COPY_MIN_PIXELS)
252	    {
253	      return false;
254	    }
255	
256	  src_addr = (uintptr_t)src->data + src_y * src->header.stride +
257	             src_x * sizeof(uint16_t);
258	  dest_addr = (uintptr_t)dest->data + dest_y * dest->header.stride +
259	              dest_x * sizeof(uint16_t);
260	  src_end = src_addr + (height - 1) * src->header.stride +
261	            width * sizeof(uint16_t);
262	  dest_end = dest_addr + (height - 1) * dest->header.stride +
263	             width * sizeof(uint16_t);
264	
265	#ifndef CONFIG_ARMV7M_DCACHE_WRITETHROUGH
266	  up_flush_dcache(src_addr, src_end);
267	  up_flush_dcache(dest_addr, dest_end);
268	#endif
269	  vg_dma2d_prepare();
270	  vg_dma2d_putreg(src_addr, VG_DMA2D_FGMAR);
271	  vg_dma2d_putreg(src_stride - width, VG_DMA2D_FGOR);
272	  vg_dma2d_putreg(VG_DMA2D_PF_RGB565, VG_DMA2D_FGPFCCR);
273	  vg_dma2d_putreg(VG_DMA2D_PF_RGB565, VG_DMA2D_OPFCCR);
274	  vg_dma2d_putreg(dest_addr, VG_DMA2D_OMAR);
275	  vg_dma2d_putreg(dest_stride - width, VG_DMA2D_OOR);
276	  vg_dma2d_putreg((width << 16) | height, VG_DMA2D_NLR);
277	
278	  start = vg_dma2d_time_us();
279	  vg_dma2d_putreg(VG_DMA2D_CR_M2M | VG_DMA2D_CR_TEIE |
280	                  VG_DMA2D_CR_TCIE | VG_DMA2D_CR_CEIE |
281	                  VG_DMA2D_CR_START, VG_DMA2D_CR);
282	  ret = vg_dma2d_wait();
283	  g_dma2d_total_us += vg_dma2d_time_us() - start;
284	  if (ret < 0)
285	    {
286	      g_dma2d_errors++;
287	      g_dma2d_fallbacks++;
288	      return false;
289	    }
290	
291	  up_invalidate_dcache(dest_addr, dest_end);
292	  g_dma2d_copy_tasks++;
293	  g_dma2d_copy_pixels += width * height;
294	  return true;
295	}
