42	function Get-IntelHexAddressRange {
43	  param([Parameter(Mandatory = $true)][string]$Path)
44	
45	  [int64]$baseAddress = 0
46	  $minAddress = $null
47	  [int64]$maxAddress = 0
48	
49	  foreach ($line in Get-Content -LiteralPath $Path) {
50	    if ([string]::IsNullOrWhiteSpace($line) -or $line[0] -ne ':') {
51	      continue
52	    }
53	
54	    [int64]$byteCount = [Convert]::ToInt32($line.Substring(1, 2), 16)
55	    [int64]$offset = [Convert]::ToInt32($line.Substring(3, 4), 16)
56	    $recordType = [Convert]::ToInt32($line.Substring(7, 2), 16)
57	
58	    switch ($recordType) {
59	      0 {
60	        [int64]$start = $baseAddress + $offset
61	        [int64]$end = $start + $byteCount
62	        if ($null -eq $minAddress -or $start -lt $minAddress) {
63	          $minAddress = $start
64	        }
65	        if ($end -gt $maxAddress) {
66	          $maxAddress = $end
67	        }
68	      }
69	      2 { $baseAddress = ([int64][Convert]::ToInt32($line.Substring(9, 4), 16)) -shl 4 }
70	      4 { $baseAddress = ([int64][Convert]::ToInt32($line.Substring(9, 4), 16)) -shl 16 }
71	    }
72	  }
73	
74	  if ($null -eq $minAddress) {
75	    throw "No data records were found in Intel HEX file: $Path"
76	  }
77	
78	  return [pscustomobject]@{ Min = [int64]$minAddress; Max = $maxAddress }
79	}
